    dict(name='moss-gentle-wren', initials='MW', role='librarian', repo='hive', task='Clarify the inspection boundary', id='demo-43', harness='Pi', model='GPT-5', state='running', age='12m', start='14:20', offset=60, color='peach'),
    dict(name='river-calm-lynx', initials='RL', role='worker', repo='agents', task='Tighten the browser skill', id='demo-44', harness='Codex', model='GPT-5', state='running', age='6m', start='14:26', offset=80, color='blue'),
    dict(name='pearl-steady-moth', initials='PM', role='reviewer', repo='agents', task='Check the new session hooks', id='demo-45', harness='Claude', model='Sonnet', state='starting', age='1m', start='14:31', offset=96, color='lavender'),
