common = '''
*{box-sizing:border-box}body{margin:0;font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:var(--bg)}button,input,select{font:inherit}button,select{cursor:pointer}button{color:inherit}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--accent);outline-offset:3px}button{border:0}h1,h2,h3,p{margin:0}h1{letter-spacing:-1.6px;line-height:1.1}small,.muted{color:var(--muted)}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}.eyebrow{font-size:10px;font-weight:650;text-transform:uppercase;letter-spacing:1.6px}.row{display:flex;align-items:center;gap:12px}.between{justify-content:space-between}.brand{font-weight:750;font-size:22px;letter-spacing:-1px}.brand svg{width:30px;height:30px;color:var(--accent)}.badge{display:inline-flex;align-items:center;gap:7px;border-radius:30px;padding:4px 9px;font-size:11px;font-weight:550;white-space:nowrap}.badge:before{content:"";width:5px;height:5px;border-radius:50%;background:currentColor}.running{background:var(--green-bg);color:var(--green)}.starting{background:var(--amber-bg);color:var(--amber)}.tools{display:flex;gap:8px;flex-wrap:wrap}.tools input,.tools select{background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:7px;padding:9px 12px;min-width:0}.tools input{width:220px}.avatar{display:grid;place-items:center;width:37px;height:37px;flex-shrink:0;border-radius:10px;font-size:11px;font-weight:700}.mint{background:#d7eee2;color:#255642}.lavender{background:#e9e1f7;color:#684d90}.peach{background:#fbe6d7;color:#9a5b35}.blue{background:#e0eaf8;color:#41689b}.note{font-size:11px;line-height:1.7;color:var(--muted)}.preview{font-size:10px;letter-spacing:.8px;text-transform:uppercase;border:1px solid var(--line);padding:5px 9px;border-radius:5px;color:var(--muted)}[hidden]{display:none!important}.empty{padding:35px;text-align:center;border:1px dashed var(--line);border-radius:10px}.inspect{padding:0;background:transparent;text-align:left;font-weight:600}.inspect:hover{text-decoration:underline;text-underline-offset:4px}.count{font-variant-numeric:tabular-nums}.view-footer{display:flex;justify-content:space-between;gap:20px;margin-top:22px;font-size:11px;color:var(--muted)}dialog{background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:16px;width:min(530px,calc(100% - 30px));padding:28px;box-shadow:0 25px 100px #0004}dialog::backdrop{background:#101b29aa;backdrop-filter:blur(4px)}dialog h2{font-size:22px;margin:20px 0 4px;letter-spacing:-.6px}dialog dl{display:grid;grid-template-columns:125px 1fr;gap:14px;font-size:13px;margin:25px 0}dialog dt{color:var(--muted)}dialog dd{margin:0;overflow-wrap:anywhere}dialog .close{background:var(--bg);border:1px solid var(--line);border-radius:6px;padding:6px 12px}dialog .note{border-top:1px solid var(--line);padding-top:18px}.title-row{display:flex;align-items:flex-end;justify-content:space-between;gap:24px}.search-label{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
@media(max-width:700px){.title-row{align-items:flex-start;flex-direction:column}.tools{width:100%}.tools input{flex:1}.view-footer{flex-direction:column;gap:6px}}
'''
logo = '''<span class="brand row"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M16 2 28 9v14L16 30 4 23V9Z" stroke="currentColor" stroke-width="2"/><path d="m10 12 6-4 6 4v8l-6 4-6-4Z" fill="currentColor"/></svg>colony<span style="color:var(--muted);font-weight:350">/</span></span>'''
def badge(b): return f'<span class="badge {b["state"]}">{b["state"].capitalize()}</span>'
def av(b): return f'<span class="avatar {b["color"]}" aria-hidden="true">{b["initials"]}</span>'
def attrs(b): return f'data-bee="{b["id"]}" data-repo="{b["repo"]}" data-state="{b["state"]}"'
def inspect(b,label=None): return f'<button class="inspect" data-inspect="{b["id"]}">{label or b["name"]}</button>'
def tools(): return '''<div class="tools"><label class="search-label" for="search">Find a bee or task</label><input id="search" placeholder="Find a bee or task…" type="search"><label class="search-label" for="repo">Repository</label><select id="repo"><option value="all">All repositories</option><option>hive</option><option>agents</option></select><label class="search-label" for="state">Recorded attempt state</label><select id="state"><option value="all">All active states</option><option value="running">Running</option><option value="starting">Starting</option></select></div>'''
footer = '''<footer class="view-footer"><span>Sample snapshot · 14:32:00 · Not connected to your daemon</span><span>Recorded attempt state ≠ verified process liveness</span></footer>'''
import json
script = '''
const bees = DATA;
const search = document.querySelector('#search');
const repo = document.querySelector('#repo');
const state = document.querySelector('#state');
function filter(){let n=0;for(const el of document.querySelectorAll('[data-bee]')){const b=bees.find(b=>b.id===el.dataset.bee);const match=(repo.value==='all'||b.repo===repo.value)&&(state.value==='all'||b.state===state.value)&&Object.values(b).join(' ').toLowerCase().includes(search.value.toLowerCase());el.hidden=!match;if(match)n++;}document.querySelector('#visible').textContent=n;document.querySelector('#empty').hidden=n!==0;for(const group of document.querySelectorAll('[data-group]')){group.hidden=![...group.querySelectorAll('[data-bee]')].some(e=>!e.hidden);}}
search.addEventListener('input',filter);repo.addEventListener('change',filter);state.addEventListener('change',filter);
const dialog=document.querySelector('dialog');
for(const button of document.querySelectorAll('[data-inspect]')){button.addEventListener('click',()=>{const b=bees.find(b=>b.id===button.dataset.inspect);document.querySelector('#detail-title').textContent=b.name;document.querySelector('#detail-task').textContent=b.task;for(const key of ['role','repo','id','harness','model','state','start'])document.querySelector('[data-detail="'+key+'"]').textContent=b[key];dialog.showModal();});}
document.querySelector('#close').addEventListener('click',()=>dialog.close());
'''.replace('DATA',json.dumps(bees))
dialog = '''<dialog aria-labelledby="detail-title"><div class="row between"><span class="eyebrow">Attempt details · sample data</span><button id="close" class="close" aria-label="Close attempt details">Close ×</button></div><h2 id="detail-title"></h2><p id="detail-task" class="muted"></p><dl><dt>Bee kind</dt><dd data-detail="role"></dd><dt>Repository</dt><dd data-detail="repo"></dd><dt>Task bead</dt><dd data-detail="id" class="mono"></dd><dt>Harness</dt><dd data-detail="harness"></dd><dt>Model</dt><dd data-detail="model"></dd><dt>Recorded state</dt><dd data-detail="state"></dd><dt>Reserved at</dt><dd><span data-detail="start"></span> · attempt 1</dd></dl><p class="note">Read-only design prototype. No daemon, tracker or process was queried. In the real UI, timestamped observations stay distinct from verified process liveness.</p></dialog>'''
empty = '<p id="empty" class="empty" hidden>No bees match these filters.</p>'
def page(name,css,body):
    result='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+name+' · Colony concept</title><style>'+common+css+'</style></head><body>'+body+dialog+'<script>'+script+'</script></body></html>'
    (out/(name.lower().replace(' ','-')+'.html')).write_text(result)
    return result

